require('bytenode');
const fs = require('fs');
const path = require('path');
const glob = require('glob');
const rimraf = require('rimraf');
const dotenv = require('dotenv');
dotenv.config({ path: path.resolve(process.cwd(), 'cucumber-config/parameters') });
if ('null' != process.env.userStoredValuesFile && process.env.userStoredValuesFile) {
    if (process.env.userStoredValuesProcessed === undefined || process.env.userStoredValuesProcessed === 'false') {
        if (fs.existsSync(path.join(path.resolve(process.cwd()), process.env.userStoredValuesFile))) {
            dotenv.config({
                path: path.join(path.resolve(process.cwd()), process.env.userStoredValuesFile),
            });
        } else {
            console.log(
                '\x1b[31m%s\x1b[0m',
                `parameter userStoredValuesFile: ${process.env.userStoredValuesFile} file not found`,
            );
            process.exit(1);
        }
    }
    process.env.userStoredValuesProcessed = 'true';
}
const allureReporter = require('@wdio/allure-reporter').default;
const { createEnvironmentProperties, getParameters } = require('./environment');
const stepDefinitionHelper = require('./step-definition-helper.js');
const pj = require(path.resolve(process.cwd(), 'package.json'));
const { checkLocale } = require('./localeCheck');
const packageName = pj.name;
// Main configuration values

// Timeout values
const implicitTimeout = 'timeout' in process.env ? Number(process.env.timeout) : 10000;
const waitforTimeout = 'timeoutWaitfor' in process.env ? Number(process.env.timeoutWaitfor) : 200000;
const cucumberTimeout = 'timeoutCucumber' in process.env ? Number(process.env.timeoutCucumber) : 300000;
process.env.timeout = implicitTimeout;
process.env.timeoutWaitfor = waitforTimeout;
process.env.timeoutCucumber = cucumberTimeout;

const connectionRetryTimeout = 120000;

process.env.timeoutPrints = process.env.timeoutPrints ? Number(process.env.timeoutPrints) : 120000;
process.env.timeoutLocks = process.env.timeoutLocks ? Number(process.env.timeoutLocks) : 240000;

if (
    cucumberTimeout < implicitTimeout ||
    cucumberTimeout < waitforTimeout ||
    cucumberTimeout < process.env.timeoutPrints ||
    cucumberTimeout < process.env.timeoutLocks
) {
    console.log(
        '\x1b[31m%s\x1b[0m',
        'timeoutCucumber environment parameter should be greater than other timeout parameter values',
    );
    process.exit(1);
}

checkLocale();

const { report_folder } = getParameters();
const reportFolder = report_folder || 'report';
const cfgReportDir = path.join(process.cwd(), reportFolder);

var cfgStepDefinitions;
var cfgFeatures;
var cfgSuite;
var cfgBaseUrl;
var cfgScreenshotsPath;
const matchAllFeaturesToken = '/**/*.feature';
process.env.downloadFolder =
    process.env.DOWNLOAD_FOLDER || process.env.downloadFolder || process.env.USERPROFILE + '\\Downloads';
console.log(cfgStepDefinitions);

const flatten = arr => arr.reduce((a, b) => a.concat(Array.isArray(b) ? flatten(b) : b), []);
switch (packageName) {
    ////X3-CUCUMBER Development
    case '@sage/x3-automatedtestplatform':
        cfgStepDefinitions = stepDefinitionHelper.getStepDefinitionFiles([
            path.resolve(__dirname + '/../lib/step-definitions') + '/',
        ]);

        cfgFeatures = [...glob.sync(path.resolve(process.cwd(), 'features') + matchAllFeaturesToken)];

        cfgSuite = undefined;

        cfgBaseUrl = process.env.baseUrl || 'http://myX3Testenvironment:8124'; //overwritten later in cloud.js file... should be removed ?

        cfgScreenshotsPath = undefined;
        break;
    ////Packaged library
    default:
        let scopeName = '@sage';
        if (packageName.startsWith('@')) {
            scopeName = packageName.substring(0, packageName.indexOf('/'));
        }

        cfgStepDefinitions = glob.sync(
            path.resolve(
                process.cwd(),
                `node_modules/${scopeName}/x3-automatedtestplatform/build/step-definitions/**/*.js`,
            ),
        );

        cfgFeatures = [
            ...glob.sync(path.resolve(process.cwd(), 'PreIntegration') + matchAllFeaturesToken),
            ...glob.sync(path.resolve(process.cwd(), 'Integration') + matchAllFeaturesToken),
        ];

        if (fs.existsSync(path.resolve(process.cwd(), 'cucumber-config/suites.json'))) {
            cfgSuite = require(path.resolve(process.cwd(), 'cucumber-config/suites.json'));
        } else {
            cfgSuite = undefined;
        }

        cfgBaseUrl = process.env.baseUrl || 'http://myX3Testenvironment:8124'; //overwritten later in cloud.js file... should be removed ?

        cfgScreenshotsPath = path.resolve(cfgReportDir + '/screenshots') + '/';
        break;
}

const config = {
    //
    // ====================
    // Runner Configuration
    // ====================
    //
    // WebdriverIO allows it to run your tests in arbitrary locations (e.g. locally or
    // on a remote machine).
    runner: 'local',
    //
    //
    // =====================
    // ts-node Configurations
    // =====================
    //
    // You can write tests using TypeScript to get autocompletion and type safety.
    // You will need typescript and ts-node installed as devDependencies.
    // WebdriverIO will automatically detect if these dependencies are installed
    // and will compile your config and tests for you.
    // If you need to configure how ts-node runs please use the
    // environment variables for ts-node or use wdio config's autoCompileOpts section.
    //
    autoCompileOpts: {
        autoCompile: true,
        // see https://github.com/TypeStrong/ts-node#cli-and-programmatic-options
        // for all available options
        tsNodeOpts: {
            transpileOnly: true,
            project: path.resolve(__dirname + '/../tsconfig.json'),
        },
        // tsconfig-paths is only used if "tsConfigPathsOpts" are provided, if you
        // do please make sure "tsconfig-paths" is installed as dependency
        //tsConfigPathsOpts: {
        //    baseUrl: './'
        //}
    },
    //
    // Override default path ('/wd/hub') for chromedriver service.
    //
    // ==================
    // Specify Test Files
    // ==================
    // Define which test specs should run. The pattern is relative to the directory
    // from which `wdio` was called. Notice that, if you are calling `wdio` from an
    // NPM script (see https://docs.npmjs.com/cli/run-script) then the current working
    // directory is where your package.json resides, so `wdio` will be called from there.
    //
    specs: cfgFeatures,
    // Patterns to exclude.
    exclude: [
        // 'path/to/excluded/files'
    ],
    // Automation Protocol (see: https://webdriver.io/blog/2019/09/16/devtools.html)
    automationProtocol: 'devtools',
    //
    // ============
    // Capabilities
    // ============
    // Define your capabilities here. WebdriverIO can run multiple capabilities at the same
    // time. Depending on the number of capabilities, WebdriverIO launches several test
    // sessions. Within your capabilities you can overwrite the spec and exclude options in
    // order to group specific specs to a specific capability.
    //
    // First, you can define how many instances should be started at the same time. Let's
    // say you have 3 different capabilities (Chrome, Firefox, and Safari) and you have
    // set maxInstances to 1; wdio will spawn 3 processes. Therefore, if you have 10 spec
    // files and you set maxInstances to 10, all spec files will get tested at the same time
    // and 30 processes will get spawned. The property handles how many capabilities
    // from the same test should run tests.
    //
    maxInstances: 1,
    //
    // If you have trouble getting all important capabilities together, check out the
    // Sauce Labs platform configurator - a great tool to configure your capabilities:
    // https://docs.saucelabs.com/reference/platforms-configurator
    //
    capabilities: [
        {
            // maxInstances can get overwritten per capability. So if you have an in-house Selenium
            // grid with only 5 firefox instances available you can make sure that not more than
            // 5 instances get started at a time.
            maxInstances: 1,
            //
            browserName: 'chrome',
            // If outputDir is provided WebdriverIO can capture driver session logs
            // it is possible to configure which logTypes to include/exclude.
            // excludeDriverLogs: ['*'], // pass '*' to exclude all driver session logs
            // excludeDriverLogs: ['bugreport', 'server'],
        },
    ],
    //
    // ===================
    // Test Configurations
    // ===================
    // Define all options that are relevant for the WebdriverIO instance here
    //
    // Level of logging verbosity: trace | debug | info | warn | error | silent
    logLevel: 'warn',
    //
    // Set specific log levels per logger
    // loggers:
    // - webdriver, webdriverio
    // - @wdio/applitools-service, @wdio/browserstack-service, @wdio/devtools-service, @wdio/sauce-service
    // - @wdio/mocha-framework, @wdio/jasmine-framework
    // - @wdio/local-runner, @wdio/lambda-runner
    // - @wdio/sumologic-reporter
    // - @wdio/cli, @wdio/config, @wdio/sync, @wdio/utils
    // Level of logging verbosity: trace | debug | info | warn | error | silent
    // logLevels: {
    //     webdriver: 'info',
    //     '@wdio/applitools-service': 'info'
    // },
    //
    // If you only want to run your tests until a specific amount of tests have failed use
    // bail (default is 0 - don't bail, run all tests).
    bail: 0,
    //
    // Set a base URL in order to shorten url command calls. If your `url` parameter starts
    // with `/`, the base url gets prepended, not including the path portion of your baseUrl.
    // If your `url` parameter starts without a scheme or `/` (like `some/path`), the base url
    // gets prepended directly.
    baseUrl: cfgBaseUrl,
    //
    // Default timeout for all waitFor* commands.
    waitforTimeout: waitforTimeout,
    //
    // Default timeout in milliseconds for request
    // if Selenium Grid doesn't send response
    connectionRetryTimeout: connectionRetryTimeout,
    //
    // Default request retries count
    connectionRetryCount: 1,
    //
    // Test runner services
    // Services take over a specific job you don't want to take care of. They enhance
    // your test setup with almost no effort. Unlike plugins, they don't add new
    // commands. Instead, they hook themselves up into the test process.
    services: ['devtools', 'shared-store'],
    // Framework you want to run your specs with.
    // The following are supported: Mocha, Jasmine, and Cucumber
    // see also: https://webdriver.io/docs/frameworks.html
    //
    // Make sure you have the wdio adapter package for the specific framework installed
    // before running any tests.
    framework: 'cucumber',
    //
    // The number of times to retry the entire specfile when it fails as a whole
    // specFileRetries: 1,
    //
    // Test reporter for stdout.
    // The only one supported by default is 'dot'
    // see also: https://webdriver.io/docs/dot-reporter.html
    // reporters: ['dot', 'allure', 'json', 'cucumber'],
    reporters: [
        'dot',
        'spec',
        [
            'allure',
            {
                outputDir: path.resolve(cfgReportDir + '/allure-results'),
                disableWebdriverStepsReporting: true,
                disableWebdriverScreenshotsReporting: false,
                useCucumberStepReporter: true,
                disableMochaHooks: false,
            },
        ],
    ],
    screenshotPath: cfgScreenshotsPath,
    // If you are using Cucumber you need to specify the location of your step definitions.
    cucumberOpts: {
        require: cfgStepDefinitions,
        // <boolean> show full backtrace for errors
        backtrace: true,
        compiler: ['ts:ts-node/register', 'js:babel-register'],
        requireModule: [() => { }],
        // <boolean> invoke formatters without executing steps
        dryRun: false,
        // <boolean> abort the run on first failure
        failFast: true,
        // <string[]> (type[:path]) specify the output format, optionally supply PATH to redirect formatter output (repeatable)
        format: ['pretty'],
        // <boolean> disable colors in formatter output
        colors: true,
        // <boolean> hide step definition snippets for pending steps
        snippets: true,
        // <boolean> hide source uris
        source: true,
        // <string[]> (name) specify the profile to use
        profile: [],
        // <boolean> fail if there are any undefined or pending steps
        strict: true,
        tagsInTitle: false,
        timeout: cucumberTimeout, // <number> timeout for step definitions
        ignoreUndefinedDefinitions: false, // <boolean> Enable this config to treat undefined definitions as warnings.
    },
    //
    // =====
    // Hooks
    // =====
    // WebdriverIO provides several hooks you can use to interfere with the test
    // process in order to enhance it and to build services around it. You can
    // either apply a single function or an array of methods to it. If one of
    // them returns with a promise, WebdriverIO will wait until that promise got
    // resolved to continue.
    //
    // Gets executed once before all workers get launched.
    onPrepare: (config, capabilities) => {
        // Log details moved here to avoid duplication in every thread
        rimraf.sync(path.resolve(cfgReportDir + '/allure-results'));
    },

    //
    // Gets executed before test execution begins. At this point you can access
    // all global variables, such as `browser`. It is the perfect place to
    // define custom commands.
    before: () => {
        require('bytenode');
        browser.setTimeout({ implicit: implicitTimeout });

        /**
         * Setup the Chai assertion framework
         */
        const chai = require('chai');
        global.expect = chai.expect;
        global.assert = chai.assert;
        global.should = chai.should();
    },
    beforeFeature: (uri, feature) => {
        process.env.FEATURE_PATH = uri;
    },
    afterScenario: function (world, result, context) {
        var featureName = world.gherkinDocument.uri.toString();
        var pathSeparator;
        if (featureName.includes('\\')) {
            pathSeparator = '\\';
        } else {
            pathSeparator = '/';
        }
        featureName = featureName.substring(featureName.lastIndexOf(pathSeparator) + 1);
        allureReporter.addArgument('Feature', featureName);
    },
    afterStep: function (uri, feature, { error, result, duration, passed }, stepData, context) { },
    afterFeature: suite => { },
    after: (result, capabilities, specs) => {
        createEnvironmentProperties();
    },
    // Gets executed after all workers got shut down and the process is about to
    // exit. It is not possible to defer the end of the process using a promise.
    onComplete: (exitCode, config) => { },
};

// Check for development config file and use that.
const existspath = 'devconf.js';
const requirepath = `../${existspath}`;
if (fs.existsSync(existspath)) {
    const dev = require(requirepath);
    dev.updateConfig(config);
}

exports.config = config;
